const unreconciledBankLines = `-- name: UnreconciledBankLines :many
SELECT l.id AS line_id, e.id AS entry_id, e.number, e.business_date, e.description, e.source_type, e.source_label,
       (l.debit_amount - l.credit_amount)::numeric AS amount,
       coalesce(p.reference, '')::text AS payment_reference, coalesce(p.number, '')::text AS payment_number,
       coalesce(p.party_name, '')::text AS party_name
FROM journal_lines l
JOIN journal_entries e ON e.id = l.journal_entry_id
LEFT JOIN payments p ON p.journal_entry_id = e.id
WHERE e.status = 'posted' AND l.account_id = $1
  AND e.business_date BETWEEN $2 AND $3
  AND NOT EXISTS (SELECT 1 FROM bank_statement_lines s WHERE s.journal_line_id = l.id AND s.status = 'matched')
ORDER BY e.business_date, e.number, l.line_no
LIMIT 2000
`

type UnreconciledBankLinesParams struct {
	AccountID uuid.UUID
	DateFrom  clock.BusinessDate
	DateTo    clock.BusinessDate
}

type UnreconciledBankLinesRow struct {
	LineID           uuid.UUID
	EntryID          uuid.UUID
	Number           pgtype.Text
	BusinessDate     clock.BusinessDate
	Description      string
	SourceType       string
	SourceLabel      string
	Amount           decimal.Decimal
	PaymentReference string
	PaymentNumber    string
	PartyName        string
}

func (q *Queries) UnreconciledBankLines(ctx context.Context, arg UnreconciledBankLinesParams) ([]UnreconciledBankLinesRow, error) {
	rows, err := q.db.Query(ctx, unreconciledBankLines, arg.AccountID, arg.DateFrom, arg.DateTo)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []UnreconciledBankLinesRow
	for rows.Next() {
		var i UnreconciledBankLinesRow
		if err := rows.Scan(
			&i.LineID,
			&i.EntryID,
			&i.Number,
			&i.BusinessDate,
			&i.Description,
			&i.SourceType,
			&i.SourceLabel,
			&i.Amount,
			&i.PaymentReference,
			&i.PaymentNumber,
			&i.PartyName,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

